<script>
const chipsLivresHtml={};
function abrirModalRejeicao(){const modal=document.getElementById('modal-rejeicao');modal?.showModal();setTimeout(()=>document.getElementById('motivo-rejeicao')?.focus(),100)}
function fecharModalRejeicao(){document.getElementById('modal-rejeicao')?.close()}
function abrirModalDivergencia(){const modal=document.getElementById('modal-divergencia');modal?.showModal();setTimeout(()=>document.getElementById('observacao-divergencia')?.focus(),100)}
function fecharModalDivergencia(){document.getElementById('modal-divergencia')?.close()}
function abrirModalInicio(){document.getElementById('modal-inicio')?.showModal()}
function fecharModalInicio(){document.getElementById('modal-inicio')?.close()}
function confirmarInicio(){const f=document.getElementById('inicio'),botao=document.getElementById('confirmar-inicio');botao.disabled=true;botao.textContent='Iniciando...';const enviar=()=>f.submit();if(navigator.geolocation){navigator.geolocation.getCurrentPosition(p=>{document.getElementById('lat').value=p.coords.latitude;document.getElementById('lng').value=p.coords.longitude;enviar()},enviar,{timeout:5000})}else enviar()}
function atualizarCamera(id){const area=document.getElementById(id);if(!area)return;const total=area.querySelectorAll('.camera-input[data-filled="1"]').length,max=Number(area.dataset.max||0),botoes=area.querySelectorAll('.camera-choice'),contador=area.querySelector('.camera-count');botoes.forEach(botao=>botao.disabled=total>=max);contador.textContent=total>=max?'Limite de fotos atingido':`${total} de ${max} foto(s) selecionada(s)`}
function resumirNomeFoto(nome){if(nome.length<=24)return nome;const ponto=nome.lastIndexOf('.'),extensao=ponto>0?nome.slice(ponto):'',base=ponto>0?nome.slice(0,ponto):nome;return `${base.slice(0,10)}…${base.slice(-6)}${extensao}`}
function adicionarFoto(id,origem){const area=document.getElementById(id);if(!area)return;const total=area.querySelectorAll('.camera-input[data-filled="1"]').length,max=Number(area.dataset.max||0);if(total>=max)return;const input=document.createElement('input');input.type='file';input.name='fotos[]';input.accept='image/*';if(origem==='camera')input.setAttribute('capture','environment');input.className='camera-input';input.addEventListener('change',()=>{if(!input.files?.length){input.remove();atualizarCamera(id);return}input.dataset.filled='1';const arquivo=input.files[0],url=URL.createObjectURL(arquivo),linha=document.createElement('div');linha.className='camera-file';const preview=document.createElement('img');preview.className='camera-preview';preview.src=url;preview.alt='Prévia da foto selecionada';const info=document.createElement('div');info.className='camera-file-info';const titulo=document.createElement('strong');titulo.textContent=`Foto ${area.querySelectorAll('.camera-file').length+1} · ${origem==='camera'?'Câmera':'Galeria'}`;const nome=document.createElement('span');nome.textContent=resumirNomeFoto(arquivo.name);nome.title=arquivo.name;info.append(titulo,nome);const remover=document.createElement('button');remover.type='button';remover.className='camera-remove';remover.textContent='Remover';remover.addEventListener('click',()=>{URL.revokeObjectURL(url);input.remove();linha.remove();atualizarCamera(id)});linha.append(preview,info,remover);area.querySelector('.camera-list').append(linha);atualizarCamera(id)});area.append(input);input.click()}
function atualizarChipDoRastreador(contexto){const rastreador=document.getElementById(`rastreador-${contexto}`),chip=document.getElementById(`chip-${contexto}`),valor=document.getElementById(`chip-${contexto}-valor`);if(!rastreador||!chip||!valor)return;const opcao=rastreador.options[rastreador.selectedIndex],chipId=opcao?.dataset.chipId||'',chipLabel=opcao?.dataset.chipLabel||'';if(chipId){chip.innerHTML='';chip.add(new Option(chipLabel,chipId,true,true));chip.disabled=true;valor.value=chipId;return}const selecionado=valor.value;chip.innerHTML=chipsLivresHtml[contexto]||'';chip.disabled=contexto==='instalacao'?!rastreador.value:false;chip.value=selecionado;valor.value=chip.value}
function atualizarChipInstalacao(){atualizarChipDoRastreador('instalacao')}
function atualizarChipManutencao(){atualizarChipDoRastreador('manutencao')}
document.addEventListener('DOMContentLoaded',()=>{['instalacao','manutencao'].forEach(contexto=>{const chip=document.getElementById(`chip-${contexto}`);if(chip)chipsLivresHtml[contexto]=chip.innerHTML;atualizarChipDoRastreador(contexto)});['camera-atendimento','camera-divergencia'].forEach(atualizarCamera);document.querySelectorAll('dialog.modal').forEach(modal=>modal.addEventListener('click',event=>{if(event.target===modal)modal.close()}));@if($errors->has('motivo')) abrirModalRejeicao(); @endif @if(old('form_context') === 'divergencia' && $errors->any()) abrirModalDivergencia(); @endif})
</script>
</body></html>
